import 'server-only';
import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { AwsClient } from 'aws4fetch';

/**
 * StorageService (spec §11.7): one interface, two drivers.
 *  - "s3": Cloudflare R2 (spec §11.6) or any S3-compatible private bucket (Supabase Storage, AWS S3, MinIO).
 *    Set STORAGE_DRIVER=s3, S3_ENDPOINT, S3_BUCKET, S3_ACCESS_KEY_ID, S3_SECRET_ACCESS_KEY (S3_REGION optional).
 *  - "local": files on disk under STORAGE_LOCAL_DIR (default ./.storage). Development and tests only.
 * Keys are always generated by the server (never user-supplied names, spec §9.5). Files are never public: they are
 * streamed back through authenticated routes after a permission check.
 */
export interface StorageService {
  readonly driver: 'local' | 's3';
  put(key: string, body: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<{ body: Uint8Array; contentType: string } | null>;
  delete(key: string): Promise<void>;
}

const KEY = /^[a-z0-9][a-z0-9/._-]{0,250}$/;
function checkKey(key: string) {
  if (!KEY.test(key) || key.includes('..')) throw new Error(`Unsafe storage key: ${key}`);
}

class LocalStorage implements StorageService {
  readonly driver = 'local' as const;
  constructor(private readonly root: string) {}
  private file(key: string) {
    checkKey(key);
    return path.join(this.root, key);
  }
  async put(key: string, body: Uint8Array, contentType: string) {
    const f = this.file(key);
    await fs.mkdir(path.dirname(f), { recursive: true });
    await fs.writeFile(f, body);
    await fs.writeFile(`${f}.type`, contentType);
  }
  async get(key: string) {
    const f = this.file(key);
    try {
      const [body, type] = await Promise.all([
        fs.readFile(f),
        fs.readFile(`${f}.type`, 'utf8').catch(() => 'application/octet-stream'),
      ]);
      return { body: new Uint8Array(body), contentType: type };
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw e;
    }
  }
  async delete(key: string) {
    const f = this.file(key);
    await Promise.all([fs.rm(f, { force: true }), fs.rm(`${f}.type`, { force: true })]);
  }
}

class S3Storage implements StorageService {
  readonly driver = 's3' as const;
  private readonly client: AwsClient;
  constructor(
    private readonly endpoint: string,
    private readonly bucket: string,
    accessKeyId: string,
    secretAccessKey: string,
    region: string,
  ) {
    this.client = new AwsClient({ accessKeyId, secretAccessKey, region, service: 's3' });
  }
  private url(key: string) {
    checkKey(key);
    return `${this.endpoint.replace(/\/+$/, '')}/${encodeURIComponent(this.bucket)}/${key.split('/').map(encodeURIComponent).join('/')}`;
  }
  async put(key: string, body: Uint8Array, contentType: string) {
    const res = await this.client.fetch(this.url(key), {
      method: 'PUT',
      body: body as unknown as BodyInit,
      headers: {
        'Content-Type': contentType,
        'x-amz-content-sha256': crypto.createHash('sha256').update(body).digest('hex'),
      },
    });
    if (!res.ok) throw new Error(`Storage upload failed (${res.status})`);
  }
  async get(key: string) {
    const res = await this.client.fetch(this.url(key));
    if (res.status === 404) return null;
    if (!res.ok) throw new Error(`Storage read failed (${res.status})`);
    return {
      body: new Uint8Array(await res.arrayBuffer()),
      contentType: res.headers.get('content-type') ?? 'application/octet-stream',
    };
  }
  async delete(key: string) {
    const res = await this.client.fetch(this.url(key), { method: 'DELETE' });
    if (!res.ok && res.status !== 404) throw new Error(`Storage delete failed (${res.status})`);
  }
}

let cached: StorageService | null | undefined;

/** The configured storage, or null when none is set up (features then explain that files aren't available yet). */
export function storage(): StorageService | null {
  if (cached !== undefined) return cached;
  const e = process.env;
  const driver = e.STORAGE_DRIVER ?? (e.VERCEL ? undefined : 'local');
  if (driver === 's3' && e.S3_ENDPOINT && e.S3_BUCKET && e.S3_ACCESS_KEY_ID && e.S3_SECRET_ACCESS_KEY) {
    cached = new S3Storage(
      e.S3_ENDPOINT,
      e.S3_BUCKET,
      e.S3_ACCESS_KEY_ID,
      e.S3_SECRET_ACCESS_KEY,
      e.S3_REGION ?? 'auto',
    );
  } else if (driver === 'local') {
    cached = new LocalStorage(path.resolve(e.STORAGE_LOCAL_DIR ?? '.storage'));
  } else {
    cached = null;
  }
  return cached;
}

/** Tests swap in their own instance. */
export function setStorageForTests(s: StorageService | null | undefined) {
  cached = s;
}

/** Random, server-generated object key under a fixed prefix (spec §9.5: never user-supplied names). */
export function newKey(...parts: string[]) {
  return [...parts, crypto.randomBytes(12).toString('hex')].join('/');
}

export const STORAGE_MISSING =
  'File storage isn’t set up yet. Ask your EDUsaas administrator to connect a storage bucket.';
